{"content":"#!/usr/bin/env python3
"""Maze validator + shortest-path solver.

Reads /protected/maze.txt, validates, BFS shortest path, writes /app/solution.txt.
Failure: no solution file is left behind, error to stderr, non-zero exit.
"""
import os
import sys
from collections import deque

MAZE_PATH = "/protected/maze.txt"
OUT_PATH = "/app/solution.txt"
N = 255


def fail(msg):
    print(f"Error: {msg}", file=sys.stderr)
    # Do not leave a stale solution file behind on failure.
    try:
        if os.path.exists(OUT_PATH):
            os.remove(OUT_PATH)
    except OSError as e:
        print(f"Error: could not remove stale solution file: {e}", file=sys.stderr)
    sys.exit(1)


def main():
    # File missing / unreadable.
    if not os.path.exists(MAZE_PATH):
        fail(f"maze file missing: {MAZE_PATH}")
    if not os.path.isfile(MAZE_PATH):
        fail(f"maze path is not a file: {MAZE_PATH}")

    try:
        with open(MAZE_PATH, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError as e:
        fail(f"cannot read maze file: {e}")

    if content == "" or content.strip() == "":
        fail("maze file is empty")

    lines = content.splitlines()
    if len(lines) == 0:
        fail("maze file is empty")

    # Validate header: exactly "START x y END x y".
    header = lines[0].strip()
    parts = header.split()
    if len(parts) != 6 or parts[0] != "START" or parts[3] != "END":
        fail(f'malformed header, expected \"START x y END x y\", got: {lines[0]!r}')
    try:
        sx = int(parts[1])
        sy = int(parts[2])
        ex = int(parts[4])
        ey = int(parts[5])
    except ValueError:
        fail(f"malformed header coordinates, expected integers, got: {lines[0]!r}")

    # Reject non-canonical integer tokens like "1.0", "+/-" is ok via int(),
    # but ensure round-trip sanity: tokens must parse as base-10 ints.
    # (int() already enforces this; floats like "1.5" raise ValueError above.)

    grid = lines[1:]

    # Validate grid dimensions: exactly 255 rows.
    if len(grid) != N:
        fail(f"malformed grid: expected {N} rows, got {len(grid)}")

    for i, row in enumerate(grid):
        if len(row) != N:
            fail(f"malformed grid: row {i} expected length {N}, got {len(row)}")
        for ch in row:
            if ch != "0" and ch != "1":
                fail(f"malformed grid: row {i} contains invalid character {ch!r} (only 0/1 allowed)")

    # Validate START/END in bounds.
    if not (0 <= sx < N and 0 <= sy < N):
        fail(f"START out of bounds: ({sx}, {sy})")
    if not (0 <= ex < N and 0 <= ey < N):
        fail(f"END out of bounds: ({ex}, {ey})")

    # Validate START/END on open cells. grid[y][x], y = row index.
    if grid[sy][sx] != "0":
        fail(f"START ({sx}, {sy}) is on a wall")
    if grid[ey][ex] != "0":
        fail(f"END ({ex}, {ey}) is on a wall")

    # Trivial case.
    if sx == ex and sy == ey:
        try:
            with open(OUT_PATH, "w", encoding="utf-8") as f:
                f.write("")
        except OSError as e:
            fail(f"cannot write solution file: {e}")
        sys.exit(0)

    # BFS for shortest path.
    # moves: (letter, dx, dy)
    moves = (("U", 0, -1), ("D", 0, 1), ("L", -1, 0), ("R", 1, 0))
    visited = [[False] * N for _ in range(N)]
    # parent[y][x] = (px, py, move_letter used to reach (x,y) from (px,py))
    parent = [[None] * N for _ in range(N)]
    q = deque()
    q.append((sx, sy))
    visited[sy][sx] = True
    found = False
    while q:
        x, y = q.popleft()
        if x == ex and y == ey:
            found = True
            break
        for letter, dx, dy in moves:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                if not visited[ny][nx] and grid[ny][nx] == "0":
                    visited[ny][nx] = True
                    parent[ny][nx] = (x, y, letter)
                    q.append((nx, ny))
    if not visited[ey][ex]:
        fail(f"END ({ex}, {ey}) unreachable from START ({sx}, {sy})")

    # Reconstruct path from END back to START.
    path_chars = []
    cx, cy = ex, ey
    while not (cx == sx and cy == sy):
        p = parent[cy][cx]
        if p is None:
            fail("path reconstruction failed (unreachable)")
        px, py, letter = p
        path_chars.append(letter)
        cx, cy = px, py
    path_chars.reverse()
    path = "".join(path_chars)

    try:
        with open(OUT_PATH, "w", encoding="utf-8") as f:
            f.write(path)
    except OSError as e:
        fail(f"cannot write solution file: {e}")


if __name__ == "__main__":
    main()
